    'logout-inside': [400, 765],
    'logout-text': [400, 765],
    // bottom nav bg
    'nav-bg': [400, 1760],
  }
  const out = {}
  for (const [k, [x, y]] of Object.entries(pts)) {
    const d = ctx.getImageData(x, y, 1, 1).data
    out[k] = `rgb(${d[0]},${d[1]},${d[2]}) #${[d[0],d[1],d[2]].map(v=>v.toString(16).padStart(2,'0')).join('')}`
  }
