  function px(x,y){const d=ctx.getImageData(x,y,1,1).data;return [d[0],d[1],d[2]]}
  // vertical scan at x=400 to find card edges (blue vs bg)
  const col = []
  for (let y=100;y<=340;y+=1){ const [r,g,b]=px(400,y); if(b>150&&b>r+40){col.push(y)} }
  out.card_top = col[0]; out.card_bottom = col[col.length-1]
  // horizontal scan at y=240
  const row=[]
  for(let x=20;x<=800;x+=1){const [r,g,b]=px(x,240); if(b>150&&b>r+40){row.push(x)}}
  out.card_left=row[0]; out.card_right=row[row.length-1]
  return out
}, b64)
